argv:
$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-avito-cards-c1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
const port=17447,target="5BE7D591DA96F1CAFD3416FF88E7DE17";
let ws;
try{
 const tabs=await(await fetch("http://127.0.0.1:"+port+"/json/list")).json();
 const tab=tabs.find(x=>x.id===target&&x.type==="page"&&x.url.startsWith("https://www.avito.ru/krasnoyarsk/telefony/"));
 if(!tab)throw Error("TARGET_NOT_FOUND_OR_WRONG_URL");
 ws=new WebSocket(tab.webSocketDebuggerUrl);
 const data=await Promise.race([new Promise((resolve,reject)=>{
 ws.addEventListener("open",()=>ws.send(JSON.stringify({id:42,method:"Runtime.evaluate",params:{expression:"(() => {\n const cards=[...document.querySelectorAll('[data-marker=\"item\"]')].slice(0,45);\n return {url:location.href,title:document.title,bodyLength:document.body?.innerText?.length||0,count:cards.length,cards:cards.map((el,i)=>{\n const h=el.querySelector('h3,[itemprop=\"name\"]');\n const a=h?.closest('a[href]')||el.querySelector('a[href*=\"/krasnoyarsk/telefony/\"]')||el.querySelector('a[href]');\n const p=el.querySelector('[data-marker=\"item-price\"],[itemprop=\"price\"]');\n const raw=el.innerText||'';\n return {i,name:h?.innerText?.trim().slice(0,125)||'',price:p?.innerText?.trim().slice(0,65)||'',text:raw.replace(/\\s+/g,' ').slice(0,260),url:a?.href||''};\n })};\n})()",returnByValue:true}})),{once:true});
 ws.addEventListener("message",event=>{let v=JSON.parse(event.data);if(v.id===42)resolve(v.result?.result?.value||{error:v.error?.message||v.result?.exceptionDetails?.text||"UNKNOWN"})});
 ws.addEventListener("error",reject,{once:true});
 }),new Promise((_,reject)=>setTimeout(()=>reject(Error("CDP_TIMEOUT")),9000))]);
 console.log(JSON.stringify(data));
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,150)}))}
finally{if(ws)ws.close()}
process.exit(0);
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
